fn starts_with(s: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true; // An empty prefix matches any sequence
    }
    if s.len() < p.len() {
        return false; // Sequence is shorter than the prefix
    }
    // Compare the characters of the sequence with the prefix
    for i in 0..p.len() {
        if s[i] != p[i] {
            return false; // Mismatch found
        }
    }
    true // All characters matched
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v, p)
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect() // Collect the filtered sequences into a new Vec
}

// Example usage
fn main() {
    let sequences = vec![
        vec!['a', 'b', 'c'],
        vec!['a', 'b', 'd'],
        vec!['b', 'c', 'd'],
        vec!['a', 'c', 'e'],
    ];
    let prefix = vec!['a', 'b'];
    let filtered = filter_by_prefix(sequences, prefix);
    
    for seq in filtered {
        println!("{:?}", seq);
    }
}